suppressPackageStartupMessages({library(data.table);library(ggplot2)})
BASE='almanac_conditionals/state_conditioned_bridge/program_first';d=fread(file.path(BASE,'results/program_sensitivity_associations.tsv'));P=sort(unique(d$program));d[,program:=factor(program,levels=rev(P))];d[,drug:=ifelse(drug=='crizotinib','Crizotinib','Lapatinib')];d[,status:=ifelse(associated,'Selected association','Not significant')]
p=ggplot(d,aes(r,program))+geom_vline(xintercept=0,color='grey70',linewidth=.3)+geom_segment(aes(x=0,xend=r,yend=program,color=status),linewidth=1)+geom_point(aes(color=status),size=1.8)+geom_text(data=d[associated==TRUE],aes(label='*'),nudge_x=.055,size=4)+facet_wrap(~drug,nrow=1)+scale_color_manual(values=c('Selected association'='#A73528','Not significant'='#B0B0B0'))+scale_x_continuous(limits=c(-1,1),breaks=c(-1,-.5,0,.5,1))+labs(x='Pearson correlation with sensitivity',y=NULL,title='Programs discovered before sensitivity selection',subtitle=sprintf('%d frozen programs; n=33 measured lines per drug; AU565 excluded',length(P)),caption='* BH q<0.05 across all programs and both drugs. Selection uses measured displacement\nweighted 0.25 / 0.50 / 0.25 across doses 0.05 / 0.5 / 5 uM.',color=NULL)+theme_classic(base_size=10)+theme(legend.position='bottom',plot.title=element_text(size=12,face='bold'),plot.subtitle=element_text(size=9),strip.background=element_blank(),strip.text=element_text(face='bold'),axis.text.y=element_text(size=8),plot.caption=element_text(size=8))
ggsave(file.path(BASE,'figures/program_selection.pdf'),p,width=7.6,height=max(4,2.1+.145*length(P)));ggsave(file.path(BASE,'figures/program_selection.png'),p,width=7.6,height=max(4,2.1+.145*length(P)),dpi=180)
source('almanac_conditionals/state_conditioned_bridge/program_first/scripts/07b_plot_rank_diagnostics.R')
